/* Régimes de terre (version publique, sans corrigés). */
window.TERRE={"titre":"Les régimes de terre TT, TN et IT","seances":[{"id":"T1","tp":"terre","num":"1","code":"TT","badge":"TT","titre":"Le régime TT et la protection différentielle","sections":[{"titre":"Votre mission en quatre heures","kind":"mission","blocks":[{"t":"p","s":[["Un fil abîmé touche la carcasse de la machine de Marie. Votre mission : expliquer comment la terre, le PE et le dispositif différentiel résiduel permettent de couper le défaut.",0,""]]},{"t":"h3","text":"Objectifs observables"},{"t":"p","s":[["1. Reconnaître les deux mises à la terre et tracer la boucle de défaut.",0,""]]},{"t":"p","s":[["2. Calculer le courant de défaut et la tension de contact avant coupure.",0,""]]},{"t":"p","s":[["3. Vérifier la coordination entre prise de terre et sensibilité du dispositif différentiel résiduel.",0,""]]},{"t":"p","s":[["Prérequis : Lire U, R et I ; calculer un quotient ; convertir mA en A.",0,""]]},{"t":"p","s":[["Savoirs associés : Loi d’Ohm ; conducteur PE ; masse ; prise de terre ; courant résiduel ; dispositif différentiel résiduel ; protection contre les contacts indirects.",0,""]]},{"t":"table","rows":[[[[["Durée",1,""]]],[[["Travail",1,""]]]],[[[["20 min",0,""]]],[[["Lire la mission, les objectifs et les consignes.",0,""]]]],[[[["40 min",0,""]]],[[["Comprendre les notions et lire les schémas.",0,""]]]],[[[["60 min",0,""]]],[[["Réaliser les calculs guidés.",0,""]]]],[[[["15 min",0,""]]],[[["Pause.",0,""]]]],[[[["60 min",0,""]]],[[["Traiter le dossier de diagnostic ou de choix ; exercice violet.",0,""]]]],[[[["25 min",0,""]]],[[["Répondre au questionnaire et expliquer ses résultats.",0,""]]]],[[[["20 min",0,""]]],[[["Compléter la synthèse et la grille avec l’enseignant.",0,""]]]]]},{"t":"p","s":[["Total : 240 min, pause comprise. En autonomie : lire → repérer → calculer → expliquer → demander validation. Les exercices violets proposent un approfondissement.",0,""]]}],"questions":[],"id":"sT1-0"},{"titre":"Comprendre avant de calculer","kind":"normal","blocks":[{"t":"h3","text":"Lire les deux lettres"},{"t":"p","s":[["Le premier T signifie qu’un point de la source est directement relié à la terre. Le second T signifie que les masses sont reliées à une prise de terre. Dans le cas étudié, la terre des masses est distincte de celle de la source.",0,""]]},{"t":"h3","text":"Comprendre le défaut"},{"t":"p","s":[["Une masse est une partie conductrice accessible, normalement hors tension. Un défaut d’isolement peut la mettre sous tension. Le PE relie cette masse à la terre ; il ne doit pas être coupé par un appareil de commande.",0,""]]},{"t":"h3","text":"Comprendre le dispositif différentiel résiduel"},{"t":"p","s":[["Le dispositif différentiel résiduel compare les courants qui traversent ses conducteurs actifs. Un courant qui repart par le PE crée un déséquilibre. Le PE ne traverse pas le détecteur du dispositif différentiel résiduel. Un interrupteur différentiel ne protège pas, à lui seul, contre les surcharges et les courts-circuits.",0,""]]},{"t":"h3","text":"Deux protections à distinguer"},{"t":"p","s":[["La protection de base repose notamment sur l’isolation et les enveloppes. La protection en cas de défaut utilise notamment PE, liaisons équipotentielles, terre et coupure. Un dispositif différentiel résiduel 30 mA apporte une protection complémentaire dans les cas prévus ; il ne rend pas tout contact sans danger.",0,""]]},{"t":"h3","text":"Les mots à employer"},{"t":"p","s":[["Électrisation : passage d’un courant dans le corps. Électrocution : électrisation mortelle. Contact direct : contact avec une partie active. Contact indirect : contact avec une masse devenue dangereuse à la suite d’un défaut. Le module étudie surtout les contacts indirects.",0,""]]},{"t":"h3","text":"Repères de lecture"},{"t":"p","s":[["L : phase ; N : neutre ; PE : conducteur de protection ; QF : disjoncteur. Trait rouge pointillé : défaut ou retour du défaut ; vert : liaison de protection ; bleu : neutre ; brun ou noir : phases. Les couleurs servent à lire le dessin ; elles ne donnent pas à elles seules une prescription de câblage.",0,""]]}],"questions":[],"id":"sT1-1"},{"titre":"Lire le schéma de principe","kind":"normal","blocks":[{"t":"img","src":"64f17d4238.png"},{"t":"p","s":[["Schéma fonctionnel pédagogique : protections complémentaires, limiteur de surtension IT et détails de réalisation non tous représentés. Aucun défaut réel à reproduire sur le secteur.",0,""]]},{"t":"q","num":"1","id":"q-T1-1","s":[["Nommez les éléments L, N, PE, R_A, R_B et dispositif différentiel résiduel.",0,""]],"v":false,"feuille":true},{"t":"q","num":"2","id":"q-T1-2","s":[["Tracez la boucle du défaut depuis L jusqu’au retour à la source.",0,""]],"v":false,"feuille":true},{"t":"q","num":"3","id":"q-T1-3","s":[["Pourquoi le courant de défaut ne revient-il pas entièrement par N à travers le dispositif différentiel résiduel ?",0,""]],"v":false,"feuille":true}],"questions":[{"num":"1","id":"q-T1-1","court":"Nommez les éléments L, N, PE, R_A, R_B et dispositif différentiel résiduel."},{"num":"2","id":"q-T1-2","court":"Tracez la boucle du défaut depuis L jusqu’au retour à la source."},{"num":"3","id":"q-T1-3","court":"Pourquoi le courant de défaut ne revient-il pas entièrement par N à tr"}],"id":"sT1-2"},{"titre":"Calculer et interpréter","kind":"normal","blocks":[{"t":"p","s":[["U₀ = 230 V ; R_A = 80 Ω ; R_B = 20 Ω ; défaut franc. On néglige les résistances des conducteurs, de la source et du défaut. Le courant calculé ne traverse pas une personne.",0,""]]},{"t":"p","s":[["I_d = U₀ / (R_A + R_B)",1,""]]},{"t":"p","s":[["U_c = R_A × I_d, tension masse–terre avant coupure",1,""]]},{"t":"p","s":[["Condition de coordination : R_A × IΔn ≤ U_L ; ici U_L = 50 V",1,""]]},{"t":"q","num":"4","id":"q-T1-4","s":[["Calculez I_d en ampères.",0,""]],"v":false,"feuille":true},{"t":"q","num":"5","id":"q-T1-5","s":[["Calculez U_c. Comparez-la à 50 V. Faut-il couper ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"6","id":"q-T1-6","s":[["Le disjoncteur est de calibre 16 A. I_d suffit-il à provoquer une coupure rapide par surintensité ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"7","id":"q-T1-7","s":[["Calculez R_A × IΔn pour 500 mA, puis pour 30 mA. La condition est-elle satisfaite dans les deux cas ?",0,""]],"v":false,"feuille":true}],"questions":[{"num":"4","id":"q-T1-4","court":"Calculez I_d en ampères."},{"num":"5","id":"q-T1-5","court":"Calculez U_c. Comparez-la à 50 V. Faut-il couper ?"},{"num":"6","id":"q-T1-6","court":"Le disjoncteur est de calibre 16 A. I_d suffit-il à provoquer une coup"},{"num":"7","id":"q-T1-7","court":"Calculez R_A × IΔn pour 500 mA, puis pour 30 mA. La condition est-elle"}],"id":"sT1-3"},{"titre":"Enquêter et approfondir","kind":"normal","blocks":[{"t":"p","s":[["Dossier simulé : la mesure de continuité entre la masse et la borne PE affiche OL ; le bouton TEST du dispositif différentiel résiduel fait déclencher. Un collègue affirme : « Le TEST fonctionne, donc tout va bien ! »",0,""]]},{"t":"q","num":"8","id":"q-T1-8","s":[["Expliquez ce que signifie OL dans ce contrôle et pourquoi le TEST ne valide pas la liaison PE.",0,""]],"v":false,"feuille":true},{"t":"q","num":"9","id":"q-T1-9","s":[["Indiquez deux contrôles à prévoir après remise en état : appareil à utiliser et résultat attendu.",0,""]],"v":false,"feuille":true},{"t":"q","num":"10","id":"q-T1-10","s":[["Rédigez une consigne simple à transmettre à Marie avant la remise en service.",0,""]],"v":false,"feuille":true},{"t":"q","num":"V1","id":"q-T1-V1","s":[["La terre se dégrade : R_A = 140 Ω. Refaire la vérification pour 500 mA, puis 300 mA. Quelle solution doit être réétudiée ? Une conformité à cette inégalité suffit-elle à valider toute l’installation ?",0,"v"]],"v":true,"feuille":true}],"questions":[{"num":"8","id":"q-T1-8","court":"Expliquez ce que signifie OL dans ce contrôle et pourquoi le TEST ne v"},{"num":"9","id":"q-T1-9","court":"Indiquez deux contrôles à prévoir après remise en état : appareil à ut"},{"num":"10","id":"q-T1-10","court":"Rédigez une consigne simple à transmettre à Marie avant la remise en "},{"num":"V1","id":"q-T1-V1","court":"La terre se dégrade : R_A = 140 Ω. Refaire la vérification pour 500 mA"}],"id":"sT1-4"},{"titre":"Réviser les savoirs","kind":"questionnaire","blocks":[{"t":"p","s":[["Sans regarder le cours, répondez en une ou deux phrases. Revenez ensuite au document pour compléter vos réponses avec une autre couleur.",0,""]]},{"t":"q","num":"R1","id":"q-T1-R1","s":[["Que signifie chacun des deux T ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"R2","id":"q-T1-R2","s":[["Le PE transporte-t-il normalement le courant de la charge ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"R3","id":"q-T1-R3","s":[["Quel appareil détecte un courant résiduel ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"R4","id":"q-T1-R4","s":[["Convertissez 30 mA en ampères.",0,""]],"v":false,"feuille":true},{"t":"q","num":"R5","id":"q-T1-R5","s":[["Vrai ou faux : une bonne prise de terre suffit sans coupure du défaut.",0,""]],"v":false,"feuille":true}],"questions":[{"num":"R1","id":"q-T1-R1","court":"Que signifie chacun des deux T ?"},{"num":"R2","id":"q-T1-R2","court":"Le PE transporte-t-il normalement le courant de la charge ?"},{"num":"R3","id":"q-T1-R3","court":"Quel appareil détecte un courant résiduel ?"},{"num":"R4","id":"q-T1-R4","court":"Convertissez 30 mA en ampères."},{"num":"R5","id":"q-T1-R5","court":"Vrai ou faux : une bonne prise de terre suffit sans coupure du défaut."}],"id":"sT1-5"},{"titre":"Faire le bilan de ses compétences","kind":"bilan","blocks":[{"t":"p","s":[["Nom : ________________________    Date : ______________",0,""]]},{"t":"p","s":[["Pour chaque ligne observée, cocher un seul niveau. L’élève se positionne d’abord ; l’enseignant échange avec lui et valide les éléments observés. Les critères portent sur cette activité, pas sur la totalité de la compétence.",0,""]]},{"t":"table","rows":[[[[["Compétence et critère observé",1,""]]],[[["Non\nacquis",1,""]]],[[["En cours\nd’acquisition",1,""]]],[[["Acquis",1,""]]]],[[[["C1 — Analyser les conditions de l’opération et son contexte\nRepère L, N, PE, masse et terres sur le schéma.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]],[[[["C3 — Définir une installation à l’aide de solutions préétablies\nVérifie la sensibilité du dispositif différentiel résiduel avec R_A.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]],[[[["C8 — Diagnostiquer un dysfonctionnement\nExplique une anomalie de PE ou de dispositif différentiel résiduel.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]],[[[["C11 — Compléter les documents liés aux opérations\nRédige les résultats avec unités et conclusion.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]]]},{"t":"h3","text":"Ma synthèse"},{"t":"p","s":[["À retenir : ",1,""],["Expliquez comment les protections étudiées dans cette activité limitent le danger d’un défaut.",0,""]]},{"t":"p","s":[["À retravailler : ",1,""],["Quel point voulez-vous revoir et avec quelle aide ?",0,""]]},{"t":"p","s":[["Validation enseignant : ____________________   Observation : ____________________",0,""]]}],"questions":[],"id":"sT1-6"},{"titre":"Ressources et repères","kind":"ressource","blocks":[{"t":"h3","text":"Dossiers de travail"},{"t":"p","s":[["Dossier technique : schémas, hypothèses et caractéristiques fournis dans cette activité. Dossier supports : calculatrice, crayons, ordinateur avec LibreOffice Calc ou simulateur préparé. Dossier santé et sécurité : consignes ci-dessous et règles de l’établissement.",0,""]]},{"t":"h3","text":"Conditions de travail"},{"t":"p","s":[["Les calculs utilisent des données d’exercice, pas des réglages à recopier sur une installation. U_L = 50 V alternatif est la valeur conventionnelle retenue ici ; certaines situations imposent d’autres limites. Les temps requis dépendent notamment du réseau, du circuit et des prescriptions applicables.",0,""]]},{"t":"p","s":[["Travail sur documents et simulateur. Aucun contact d’une personne avec une partie électrique, aucun court-circuit ni défaut créé sur le secteur. Toute manipulation réelle exige un support pédagogique adapté, une procédure validée et l’encadrement de l’enseignant. La réalisation de ce module ne constitue pas une habilitation.",0,""]]},{"t":"h3","text":"Références consultées le 3 octobre 2026"},{"t":"p","s":[["Référentiel MELEC 2024 : compétences C1 à C13. Les compétences retenues figurent dans la grille de cette activité. La mise en page reprend le modèle enseignant joint.",0,""]]},{"t":"p","s":[["https://sti.eduscol.education.fr/textes/bac-pro-des-metiers-de-lelectricite-et-de-ses-environnements-connectes",0,""]]},{"t":"p","s":[["INRS — Accidents d’origine électrique et prévention du risque électrique.",0,""]]},{"t":"p","s":[["https://www.inrs.fr/risques/electriques/accidents-origine-electrique.html\nhttps://www.inrs.fr/risques/electriques/prevention-risque-electrique.html",0,""]]},{"t":"p","s":[["Schneider Electric — Guide de l’installation électrique : principes TT, TN et IT ; mise en œuvre des protections IT. Appui explicatif, à compléter avec les textes applicables et les notices.",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_TT_-_Principe",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_TN_-_Principe",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_IT_-_Principe",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_IT_-_Mise_en_oeuvre_des_protections",0,""]]},{"t":"p","s":[["Cadre technique : série NF C 15-100 pour l’installation ; NF C 18-510 pour les opérations électriques. Vérifier l’édition applicable au projet. Pour un site hors de France, vérifier aussi le cadre local et les prescriptions du distributeur.",0,""]]}],"questions":[],"id":"sT1-7"}],"corrige":[]},{"id":"T2","tp":"terre","num":"2","code":"TN","badge":"TN","titre":"Le régime TN et la coupure par le disjoncteur","sections":[{"titre":"Votre mission en quatre heures","kind":"mission","blocks":[{"t":"p","s":[["Votre mission : ",1,""],["Cette fois, un défaut touche la carcasse de la perceuse. Vous suivez le trajet du courant de défaut par le PE et vérifiez que le disjoncteur coupe assez vite.",0,""]]},{"t":"h3","text":"Objectifs observables"},{"t":"p","s":[["1. Distinguer TN-S, TN-C et TN-C-S.",0,""]]},{"t":"p","s":[["2. Calculer le courant de défaut à partir de l’impédance de boucle.",0,""]]},{"t":"p","s":[["3. Comparer ce courant au seuil garantissant la coupure.",0,""]]},{"t":"p","s":[["Prérequis : Activité TT ; loi d’Ohm ; distinction entre courant nominal et courant de déclenchement.",0,""]]},{"t":"p","s":[["Savoirs associés : Boucle phase–PE ; impédance ; disjoncteur ; caractéristique temps–courant ; PE et PEN ; continuité.",0,""]]},{"t":"table","rows":[[[[["Durée",1,""]]],[[["Travail",1,""]]]],[[[["20 min",0,""]]],[[["Lire la mission, les objectifs et les consignes.",0,""]]]],[[[["40 min",0,""]]],[[["Comprendre les notions et lire les schémas.",0,""]]]],[[[["60 min",0,""]]],[[["Réaliser les calculs guidés.",0,""]]]],[[[["15 min",0,""]]],[[["Pause.",0,""]]]],[[[["60 min",0,""]]],[[["Traiter le dossier de diagnostic ou de choix ; exercice violet.",0,""]]]],[[[["25 min",0,""]]],[[["Répondre au questionnaire et expliquer ses résultats.",0,""]]]],[[[["20 min",0,""]]],[[["Compléter la synthèse et la grille avec l’enseignant.",0,""]]]]]},{"t":"p","s":[["Total : 240 min, pause comprise. En autonomie : lire → repérer → calculer → expliquer → demander validation. Les exercices violets proposent un approfondissement.",0,""]]}],"questions":[],"id":"sT2-0"},{"titre":"Comprendre avant de calculer","kind":"normal","blocks":[{"t":"h3","text":"Lire les lettres"},{"t":"p","s":[["T : un point de la source est directement relié à la terre. N : les masses sont reliées à ce point par un conducteur de protection. Le défaut crée principalement une boucle métallique ; le sol n’est pas le trajet principal du courant de défaut.",0,""]]},{"t":"h3","text":"Distinguer les variantes"},{"t":"p","s":[["TN-S : N et PE séparés. TN-C : leurs fonctions sont réunies dans un PEN. TN-C-S : une partie en PEN est suivie d’une séparation en PE et N. Le PEN ne doit pas être coupé ; après séparation, PE et N ne doivent pas être réunis en aval.",0,""]]},{"t":"h3","text":"Vérifier la coupure"},{"t":"p","s":[["I_a désigne le courant qui assure la coupure dans le temps requis, d’après la caractéristique du dispositif. Ce n’est pas son calibre I_n. On vérifie Z_s × I_a ≤ U₀, ce qui revient à I_d ≥ I_a dans le modèle étudié.",0,""]]},{"t":"h3","text":"Place des différentiels"},{"t":"p","s":[["Un dispositif différentiel résiduel peut être utilisé en TN-S ou dans la partie TN-S d’un TN-C-S. Il n’est pas utilisé dans la partie TN-C avec PEN. Une faible impédance de boucle ne dispense pas des autres protections exigées pour le circuit.",0,""]]},{"t":"h3","text":"Les mots à employer"},{"t":"p","s":[["Électrisation : passage d’un courant dans le corps. Électrocution : électrisation mortelle. Contact direct : contact avec une partie active. Contact indirect : contact avec une masse devenue dangereuse à la suite d’un défaut. Le module étudie surtout les contacts indirects.",0,""]]},{"t":"h3","text":"Repères de lecture"},{"t":"p","s":[["L : phase ; N : neutre ; PE : conducteur de protection ; QF : disjoncteur. Trait rouge pointillé : défaut ou retour du défaut ; vert : liaison de protection ; bleu : neutre ; brun ou noir : phases. Les couleurs servent à lire le dessin ; elles ne donnent pas à elles seules une prescription de câblage.",0,""]]}],"questions":[],"id":"sT2-1"},{"titre":"Lire le schéma de principe","kind":"normal","blocks":[{"t":"img","src":"c3b35af5ab.png"},{"t":"p","s":[["Schéma fonctionnel pédagogique : protections complémentaires, limiteur de surtension IT et détails de réalisation non tous représentés. Aucun défaut réel à reproduire sur le secteur.",0,""]]},{"t":"q","num":"1","id":"q-T2-1","s":[["Tracez le retour du courant de défaut. Passe-t-il principalement par le sol ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"2","id":"q-T2-2","s":[["Indiquez la différence entre N, PE et PEN.",0,""]],"v":false,"feuille":true}],"questions":[{"num":"1","id":"q-T2-1","court":"Tracez le retour du courant de défaut. Passe-t-il principalement par l"},{"num":"2","id":"q-T2-2","court":"Indiquez la différence entre N, PE et PEN."}],"id":"sT2-2"},{"titre":"Lire le schéma complémentaire","kind":"normal","blocks":[{"t":"img","src":"2e10de67b0.png"},{"t":"p","s":[["Schéma fonctionnel pédagogique : protections complémentaires, limiteur de surtension IT et détails de réalisation non tous représentés. Aucun défaut réel à reproduire sur le secteur.",0,""]]},{"t":"q","num":"3","id":"q-T2-3","s":[["Sur quel côté de la séparation PEN peut-on placer un dispositif différentiel résiduel ?",0,""]],"v":false,"feuille":true}],"questions":[{"num":"3","id":"q-T2-3","court":"Sur quel côté de la séparation PEN peut-on placer un dispositif différentiel résiduel ?"}],"id":"sT2-3"},{"titre":"Calculer et interpréter","kind":"normal","blocks":[{"t":"p","s":[["Circuit terminal TN-S 230 V, disjoncteur C16. Donnée pédagogique de sélection : I_a = 10 × I_n = 160 A, garantissant ici une coupure en moins de 0,1 s. Temps maximal retenu pour ce circuit : 0,4 s. Z_s = 0,80 Ω, boucle complète source comprise.",0,""]]},{"t":"p","s":[["I_d = U₀ / Z_s",1,""]]},{"t":"p","s":[["Z_s,max = U₀ / I_a",1,""]]},{"t":"p","s":[["Vérifier à la fois le courant requis et le temps de coupure",1,""]]},{"t":"q","num":"4","id":"q-T2-4","s":[["Calculez I_a puis I_d. La coupure est-elle garantie par les données fournies ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"5","id":"q-T2-5","s":[["Calculez Z_s,max.",0,""]],"v":false,"feuille":true},{"t":"q","num":"6","id":"q-T2-6","s":[["Après extension du câble, Z_s = 1,80 Ω. Recalculez I_d. Peut-on garantir la coupure avec la seule donnée I_a ?",0,""]],"v":false,"feuille":true}],"questions":[{"num":"4","id":"q-T2-4","court":"Calculez I_a puis I_d. La coupure est-elle garantie par les données fo"},{"num":"5","id":"q-T2-5","court":"Calculez Z_s,max."},{"num":"6","id":"q-T2-6","court":"Après extension du câble, Z_s = 1,80 Ω. Recalculez I_d. Peut-on garant"}],"id":"sT2-4"},{"titre":"Enquêter et approfondir","kind":"normal","blocks":[{"t":"p","s":[["Dossier simulé : boucle après extension 1,80 Ω. Trois propositions : A augmenter la section pour réduire Z_s ; B remplacer C16 par C32 sans autre étude ; C étudier un dispositif différentiel résiduel adapté en TN-S. Un collègue choisit B.",0,""]]},{"t":"q","num":"7","id":"q-T2-7","s":[["Classez les propositions : solution à étudier ou proposition injustifiée. Expliquez pourquoi.",0,""]],"v":false,"feuille":true},{"t":"q","num":"8","id":"q-T2-8","s":[["Indiquez deux causes possibles d’une impédance de boucle anormalement élevée.",0,""]],"v":false,"feuille":true},{"t":"q","num":"9","id":"q-T2-9","s":[["Quels documents et contrôles faut-il consulter avant de valider la modification ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"V2","id":"q-T2-V2","s":[["Dans LibreOffice Calc, entrer Z_s = 0,40 ; 0,80 ; 1,20 ; 1,80 Ω en colonne A. En B2, saisir =230/A2 puis recopier. En C2, saisir =SI(B2>=160;\"condition satisfaite\";\"à revoir\") puis recopier. Joindre le tableau et expliquer l’effet d’un câble plus long.",0,"v"]],"v":true,"feuille":true}],"questions":[{"num":"7","id":"q-T2-7","court":"Classez les propositions : solution à étudier ou proposition injustifi"},{"num":"8","id":"q-T2-8","court":"Indiquez deux causes possibles d’une impédance de boucle anormalement "},{"num":"9","id":"q-T2-9","court":"Quels documents et contrôles faut-il consulter avant de valider la mod"},{"num":"V2","id":"q-T2-V2","court":"Dans LibreOffice Calc, entrer Z_s = 0,40 ; 0,80 ; 1,20 ; 1,80 Ω en col"}],"id":"sT2-5"},{"titre":"Réviser les savoirs","kind":"questionnaire","blocks":[{"t":"p","s":[["Sans regarder le cours, répondez en une ou deux phrases. Revenez ensuite au document pour compléter vos réponses avec une autre couleur.",0,""]]},{"t":"q","num":"R1","id":"q-T2-R1","s":[["Que signifie le N de TN ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"R2","id":"q-T2-R2","s":[["En TN-S, N et PE sont-ils séparés ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"R3","id":"q-T2-R3","s":[["Un PEN peut-il être interrompu par un interrupteur ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"R4","id":"q-T2-R4","s":[["Quelle différence existe-t-il entre I_n et I_a ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"R5","id":"q-T2-R5","s":[["Si Z_s augmente, I_d augmente-t-il ou diminue-t-il ?",0,""]],"v":false,"feuille":true}],"questions":[{"num":"R1","id":"q-T2-R1","court":"Que signifie le N de TN ?"},{"num":"R2","id":"q-T2-R2","court":"En TN-S, N et PE sont-ils séparés ?"},{"num":"R3","id":"q-T2-R3","court":"Un PEN peut-il être interrompu par un interrupteur ?"},{"num":"R4","id":"q-T2-R4","court":"Quelle différence existe-t-il entre I_n et I_a ?"},{"num":"R5","id":"q-T2-R5","court":"Si Z_s augmente, I_d augmente-t-il ou diminue-t-il ?"}],"id":"sT2-6"},{"titre":"Faire le bilan de ses compétences","kind":"bilan","blocks":[{"t":"p","s":[["Nom : ________________________    Date : ______________",0,""]]},{"t":"p","s":[["Pour chaque ligne observée, cocher un seul niveau. L’élève se positionne d’abord ; l’enseignant échange avec lui et valide les éléments observés. Les critères portent sur cette activité, pas sur la totalité de la compétence.",0,""]]},{"t":"table","rows":[[[[["Compétence et critère observé",1,""]]],[[["Non\nacquis",1,""]]],[[["En cours\nd’acquisition",1,""]]],[[["Acquis",1,""]]]],[[[["C1 — Analyser les conditions de l’opération et son contexte\nIdentifie la boucle métallique et les variantes TN.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]],[[[["C3 — Définir une installation à l’aide de solutions préétablies\nVérifie I_d ≥ I_a et propose une correction argumentée.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]],[[[["C10 — Exploiter les outils numériques dans le contexte professionnel\nUtilise un tableur pour comparer plusieurs impédances.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]],[[[["C11 — Compléter les documents liés aux opérations\nRenseigne le tableau de calcul et justifie sa conclusion.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]]]},{"t":"h3","text":"Ma synthèse"},{"t":"p","s":[["À retenir : ",1,""],["Expliquez comment les protections étudiées dans cette activité limitent le danger d’un défaut.",0,""]]},{"t":"p","s":[["À retravailler : ",1,""],["Quel point voulez-vous revoir et avec quelle aide ?",0,""]]},{"t":"p","s":[["Validation enseignant : ____________________   Observation : ____________________",0,""]]}],"questions":[],"id":"sT2-7"},{"titre":"Ressources et repères","kind":"ressource","blocks":[{"t":"h3","text":"Dossiers de travail"},{"t":"p","s":[["Dossier technique : schémas, hypothèses et caractéristiques fournis dans cette activité. Dossier supports : calculatrice, crayons, ordinateur avec LibreOffice Calc ou simulateur préparé. Dossier santé et sécurité : consignes ci-dessous et règles de l’établissement.",0,""]]},{"t":"h3","text":"Conditions de travail"},{"t":"p","s":[["Les calculs utilisent des données d’exercice, pas des réglages à recopier sur une installation. U_L = 50 V alternatif est la valeur conventionnelle retenue ici ; certaines situations imposent d’autres limites. Les temps requis dépendent notamment du réseau, du circuit et des prescriptions applicables.",0,""]]},{"t":"p","s":[["Travail sur documents et simulateur. Aucun contact d’une personne avec une partie électrique, aucun court-circuit ni défaut créé sur le secteur. Toute manipulation réelle exige un support pédagogique adapté, une procédure validée et l’encadrement de l’enseignant. La réalisation de ce module ne constitue pas une habilitation.",0,""]]},{"t":"h3","text":"Références consultées le 3 octobre 2026"},{"t":"p","s":[["Référentiel MELEC 2024 : compétences C1 à C13. Les compétences retenues figurent dans la grille de cette activité. La mise en page reprend le modèle enseignant joint.",0,""]]},{"t":"p","s":[["https://sti.eduscol.education.fr/textes/bac-pro-des-metiers-de-lelectricite-et-de-ses-environnements-connectes",0,""]]},{"t":"p","s":[["INRS — Accidents d’origine électrique et prévention du risque électrique.",0,""]]},{"t":"p","s":[["https://www.inrs.fr/risques/electriques/accidents-origine-electrique.html\nhttps://www.inrs.fr/risques/electriques/prevention-risque-electrique.html",0,""]]},{"t":"p","s":[["Schneider Electric — Guide de l’installation électrique : principes TT, TN et IT ; mise en œuvre des protections IT. Appui explicatif, à compléter avec les textes applicables et les notices.",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_TT_-_Principe",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_TN_-_Principe",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_IT_-_Principe",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_IT_-_Mise_en_oeuvre_des_protections",0,""]]},{"t":"p","s":[["Cadre technique : série NF C 15-100 pour l’installation ; NF C 18-510 pour les opérations électriques. Vérifier l’édition applicable au projet. Pour un site hors de France, vérifier aussi le cadre local et les prescriptions du distributeur.",0,""]]}],"questions":[],"id":"sT2-8"}],"corrige":[]},{"id":"T3","tp":"terre","num":"3","code":"IT","badge":"IT","titre":"Le régime IT et le contrôleur d’isolement","sections":[{"titre":"Votre mission en quatre heures","kind":"mission","blocks":[{"t":"p","s":[["Un premier défaut apparaît. « La machine ne s’arrête pas ! » Le CPI donne l’alarme. Votre mission : expliquer cette continuité provisoire et empêcher un second défaut de mettre Marie en danger.",0,""]]},{"t":"h3","text":"Objectifs observables"},{"t":"p","s":[["1. Expliquer le rôle du CPI au premier défaut.",0,""]]},{"t":"p","s":[["2. Calculer un premier courant de défaut dans un modèle simplifié.",0,""]]},{"t":"p","s":[["3. Reconnaître la boucle dangereuse de deux défauts sur des conducteurs actifs différents.",0,""]]},{"t":"p","s":[["Prérequis : Activités TT et TN ; circuit fermé ; résistance et impédance ; conversion A et mA.",0,""]]},{"t":"p","s":[["Savoirs associés : Isolement ; impédance de liaison à la terre ; CPI ; alarme ; premier et second défauts ; maintenance.",0,""]]},{"t":"table","rows":[[[[["Durée",1,""]]],[[["Travail",1,""]]]],[[[["20 min",0,""]]],[[["Lire la mission, les objectifs et les consignes.",0,""]]]],[[[["40 min",0,""]]],[[["Comprendre les notions et lire les schémas.",0,""]]]],[[[["60 min",0,""]]],[[["Réaliser les calculs guidés.",0,""]]]],[[[["15 min",0,""]]],[[["Pause.",0,""]]]],[[[["60 min",0,""]]],[[["Traiter le dossier de diagnostic ou de choix ; exercice violet.",0,""]]]],[[[["25 min",0,""]]],[[["Répondre au questionnaire et expliquer ses résultats.",0,""]]]],[[[["20 min",0,""]]],[[["Compléter la synthèse et la grille avec l’enseignant.",0,""]]]]]},{"t":"p","s":[["Total : 240 min, pause comprise. En autonomie : lire → repérer → calculer → expliquer → demander validation. Les exercices violets proposent un approfondissement.",0,""]]}],"questions":[],"id":"sT3-0"},{"titre":"Comprendre avant de calculer","kind":"normal","blocks":[{"t":"h3","text":"Lire les lettres"},{"t":"p","s":[["I : la source est isolée de la terre ou reliée à la terre par une impédance élevée. T : les masses sont reliées à la terre. I ne signifie donc pas « masses isolées ».",0,""]]},{"t":"h3","text":"Premier défaut"},{"t":"p","s":[["Le courant dépend de l’impédance éventuelle, des capacités et des fuites du réseau. La poursuite du fonctionnement est conditionnelle : il faut notamment vérifier R_A × I_d1 ≤ U_L. Le courant n’est pas nécessairement nul.",0,""]]},{"t":"h3","text":"Surveillance et réparation"},{"t":"p","s":[["Le contrôleur permanent d’isolement, CPI, surveille l’isolement et signale sa dégradation. Il ne remplace pas un disjoncteur de protection. L’alarme doit conduire à localiser puis supprimer rapidement le premier défaut selon une procédure organisée.",0,""]]},{"t":"h3","text":"Deuxième défaut"},{"t":"p","s":[["Deux défauts simultanés sur des conducteurs actifs différents peuvent former une boucle de fort courant. Avec des masses interconnectées par PE, on retrouve une boucle métallique à couper. Avec des groupes de masses non interconnectés, l’étude et les protections diffèrent : ce cas n’est pas calculé ici.",0,""]]},{"t":"h3","text":"Les mots à employer"},{"t":"p","s":[["Électrisation : passage d’un courant dans le corps. Électrocution : électrisation mortelle. Contact direct : contact avec une partie active. Contact indirect : contact avec une masse devenue dangereuse à la suite d’un défaut. Le module étudie surtout les contacts indirects.",0,""]]},{"t":"h3","text":"Repères de lecture"},{"t":"p","s":[["L : phase ; N : neutre ; PE : conducteur de protection ; QF : disjoncteur. Trait rouge pointillé : défaut ou retour du défaut ; vert : liaison de protection ; bleu : neutre ; brun ou noir : phases. Les couleurs servent à lire le dessin ; elles ne donnent pas à elles seules une prescription de câblage.",0,""]]}],"questions":[],"id":"sT3-1"},{"titre":"Lire le schéma de principe","kind":"normal","blocks":[{"t":"img","src":"fba0bf4312.png"},{"t":"p","s":[["Schéma fonctionnel pédagogique : protections complémentaires, limiteur de surtension IT et détails de réalisation non tous représentés. Aucun défaut réel à reproduire sur le secteur.",0,""]]},{"t":"q","num":"1","id":"q-T3-1","s":[["Repérez la liaison de la source à la terre. Pourquoi ne s’agit-il pas d’un TT ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"2","id":"q-T3-2","s":[["Quel appareil signale la baisse d’isolement ? Comment réagir face à cette alerte ?",0,""]],"v":false,"feuille":true}],"questions":[{"num":"1","id":"q-T3-1","court":"Repérez la liaison de la source à la terre. Pourquoi ne s’agit-il pas "},{"num":"2","id":"q-T3-2","court":"Quel appareil signale la baisse d’isolement ? Quel travail faut-il org"}],"id":"sT3-2"},{"titre":"Lire le schéma complémentaire","kind":"normal","blocks":[{"t":"img","src":"b62711ce56.png"},{"t":"p","s":[["Schéma fonctionnel pédagogique : protections complémentaires, limiteur de surtension IT et détails de réalisation non tous représentés. Aucun défaut réel à reproduire sur le secteur.",0,""]]},{"t":"q","num":"3","id":"q-T3-3","s":[["Un second défaut apparaît sur L2 (machine B) alors que le premier, sur L1 (machine A), n’est pas réparé. Sur le schéma, tracez le chemin du courant : de L1, par la masse A, le PE et la masse B, jusqu’à L2. Entre quels conducteurs ce courant circule-t-il, et quelle tension le pousse ?",0,""]],"v":false,"feuille":true}],"questions":[{"num":"3","id":"q-T3-3","court":"Tracez la boucle entre L1 et L2. Quelle tension est appliquée à cette "}],"id":"sT3-3"},{"titre":"Calculer et interpréter","kind":"normal","blocks":[{"t":"p","s":[["Premier défaut : U₀ = 230 V ; Z = 1 500 Ω, supposée résistive ; R_A = 50 Ω. Résistance de terre côté source et autres impédances négligées, capacités négligées. Second défaut sur L1 et L2 : U = 400 V ; Z_boucle complète = 1,00 Ω ; I_a = 160 A pour chacun des deux départs, temps garanti < 0,1 s. Critère de temps fixé pour l’exercice : 0,4 s.",0,""]]},{"t":"p","s":[["Premier défaut : I_d1 = U₀ / (Z + R_A) ; U_c1 = R_A × I_d1",1,""]]},{"t":"p","s":[["Second défaut étudié : I_d2 = U / Z_boucle complète",1,""]]},{"t":"p","s":[["Z_boucle complète comprend les deux départs, le PE et la source : ne pas la multiplier encore par 2",1,""]]},{"t":"q","num":"4","id":"q-T3-4","s":[["Calculez I_d1 en A puis en mA ; calculez U_c1. La condition avec 50 V est-elle satisfaite ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"5","id":"q-T3-5","s":[["Calculez I_d2. Comparez-le à I_a et vérifiez le critère de temps fourni.",0,""]],"v":false,"feuille":true},{"t":"q","num":"6","id":"q-T3-6","s":[["Pourquoi ne peut-on pas déduire I_d1 = 0 pour toute installation IT dite isolée ?",0,""]],"v":false,"feuille":true}],"questions":[{"num":"4","id":"q-T3-4","court":"Calculez I_d1 en A puis en mA ; calculez U_c1. La condition avec 50 V "},{"num":"5","id":"q-T3-5","court":"Calculez I_d2. Comparez-le à I_a et vérifiez le critère de temps fourn"},{"num":"6","id":"q-T3-6","court":"Pourquoi ne peut-on pas déduire I_d1 = 0 pour toute installation IT di"}],"id":"sT3-4"},{"titre":"Enquêter et approfondir","kind":"normal","blocks":[{"t":"p","s":[["Dossier simulé : le CPI global indique 18 kΩ. Dans une simulation de localisation, l’isolement remonte à 400 kΩ lorsque le départ B est retiré du réseau ; retirer A ou C ne change presque rien. Un collègue propose de masquer l’alarme.",0,""]]},{"t":"q","num":"7","id":"q-T3-7","s":[["Quel départ suspectez-vous ? Le résultat désigne-t-il déjà un composant précis ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"8","id":"q-T3-8","s":[["Rédigez le message de maintenance : alarme, départ suspect, risque si le défaut persiste et action demandée.",0,""]],"v":false,"feuille":true},{"t":"q","num":"9","id":"q-T3-9","s":[["Après réparation, quels éléments faut-il contrôler avant de clore l’intervention ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"V3","id":"q-T3-V3","s":[["Le simulateur indique 80 kΩ, puis 40 kΩ, puis 18 kΩ d’isolement. La consigne pédagogique fixe l’alarme sous 50 kΩ. Paramétrez ce seuil, testez les trois valeurs et consignez les états. Ce seuil d’exercice n’est pas une valeur universelle à appliquer sur site.",0,"v"]],"v":true,"feuille":true}],"questions":[{"num":"7","id":"q-T3-7","court":"Quel départ suspectez-vous ? Le résultat désigne-t-il déjà un composan"},{"num":"8","id":"q-T3-8","court":"Rédigez le message de maintenance : alarme, départ suspect, risque si "},{"num":"9","id":"q-T3-9","court":"Après réparation, quels éléments faut-il contrôler avant de clore l’in"},{"num":"V3","id":"q-T3-V3","court":"Le simulateur indique 80 kΩ, puis 40 kΩ, puis 18 kΩ d’isolement. La co"}],"id":"sT3-5"},{"titre":"Réviser les savoirs","kind":"questionnaire","blocks":[{"t":"p","s":[["Sans regarder le cours, répondez en une ou deux phrases. Revenez ensuite au document pour compléter vos réponses avec une autre couleur.",0,""]]},{"t":"q","num":"R1","id":"q-T3-R1","s":[["Le I signifie-t-il que les masses ne sont pas reliées à la terre ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"R2","id":"q-T3-R2","s":[["Quel est le rôle du CPI ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"R3","id":"q-T3-R3","s":[["Peut-on ignorer un premier défaut puisque la machine fonctionne ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"R4","id":"q-T3-R4","s":[["Le second défaut étudié porte-t-il sur la même phase ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"R5","id":"q-T3-R5","s":[["L’IT garantit-il l’absence de coupure dans toutes les situations ?",0,""]],"v":false,"feuille":true}],"questions":[{"num":"R1","id":"q-T3-R1","court":"Le I signifie-t-il que les masses ne sont pas reliées à la terre ?"},{"num":"R2","id":"q-T3-R2","court":"Quel est le rôle du CPI ?"},{"num":"R3","id":"q-T3-R3","court":"Peut-on ignorer un premier défaut puisque la machine fonctionne ?"},{"num":"R4","id":"q-T3-R4","court":"Le second défaut étudié porte-t-il sur la même phase ?"},{"num":"R5","id":"q-T3-R5","court":"L’IT garantit-il l’absence de coupure dans toutes les situations ?"}],"id":"sT3-6"},{"titre":"Faire le bilan de ses compétences","kind":"bilan","blocks":[{"t":"p","s":[["Nom : ________________________    Date : ______________",0,""]]},{"t":"p","s":[["Pour chaque ligne observée, cocher un seul niveau. L’élève se positionne d’abord ; l’enseignant échange avec lui et valide les éléments observés. Les critères portent sur cette activité, pas sur la totalité de la compétence.",0,""]]},{"t":"table","rows":[[[[["Compétence et critère observé",1,""]]],[[["Non\nacquis",1,""]]],[[["En cours\nd’acquisition",1,""]]],[[["Acquis",1,""]]]],[[[["C1 — Analyser les conditions de l’opération et son contexte\nDistingue premier défaut et second défaut.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]],[[[["C6 — Régler, paramétrer les matériels de l’installation\nParamètre un seuil sur simulateur et vérifie l’alarme.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]],[[[["C8 — Diagnostiquer un dysfonctionnement\nLocalise le départ suspect à partir des résultats.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]],[[[["C12 — Communiquer entre professionnels sur l’opération\nTransmet un signalement exploitable à la maintenance.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]]]},{"t":"h3","text":"Ma synthèse"},{"t":"p","s":[["À retenir : ",1,""],["Expliquez comment les protections étudiées dans cette activité limitent le danger d’un défaut.",0,""]]},{"t":"p","s":[["À retravailler : ",1,""],["Quel point voulez-vous revoir et avec quelle aide ?",0,""]]},{"t":"p","s":[["Validation enseignant : ____________________   Observation : ____________________",0,""]]}],"questions":[],"id":"sT3-7"},{"titre":"Ressources et repères","kind":"ressource","blocks":[{"t":"h3","text":"Dossiers de travail"},{"t":"p","s":[["Pour V3 : ouvrir Simulation_CPI.html, fourni dans l’archive, avec un navigateur. Aucune connexion Internet nécessaire. Régler le seuil, saisir l’isolement et cliquer sur Tester.",0,""]]},{"t":"p","s":[["Dossier technique : schémas, hypothèses et caractéristiques fournis dans cette activité. Dossier supports : calculatrice, crayons, ordinateur avec LibreOffice Calc ou simulateur préparé. Dossier santé et sécurité : consignes ci-dessous et règles de l’établissement.",0,""]]},{"t":"h3","text":"Conditions de travail"},{"t":"p","s":[["Les calculs utilisent des données d’exercice, pas des réglages à recopier sur une installation. U_L = 50 V alternatif est la valeur conventionnelle retenue ici ; certaines situations imposent d’autres limites. Les temps requis dépendent notamment du réseau, du circuit et des prescriptions applicables.",0,""]]},{"t":"p","s":[["Travail sur documents et simulateur. Aucun contact d’une personne avec une partie électrique, aucun court-circuit ni défaut créé sur le secteur. Toute manipulation réelle exige un support pédagogique adapté, une procédure validée et l’encadrement de l’enseignant. La réalisation de ce module ne constitue pas une habilitation.",0,""]]},{"t":"h3","text":"Références consultées le 3 octobre 2026"},{"t":"p","s":[["Référentiel MELEC 2024 : compétences C1 à C13. Les compétences retenues figurent dans la grille de cette activité. La mise en page reprend le modèle enseignant joint.",0,""]]},{"t":"p","s":[["https://sti.eduscol.education.fr/textes/bac-pro-des-metiers-de-lelectricite-et-de-ses-environnements-connectes",0,""]]},{"t":"p","s":[["INRS — Accidents d’origine électrique et prévention du risque électrique.",0,""]]},{"t":"p","s":[["https://www.inrs.fr/risques/electriques/accidents-origine-electrique.html\nhttps://www.inrs.fr/risques/electriques/prevention-risque-electrique.html",0,""]]},{"t":"p","s":[["Schneider Electric — Guide de l’installation électrique : principes TT, TN et IT ; mise en œuvre des protections IT. Appui explicatif, à compléter avec les textes applicables et les notices.",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_TT_-_Principe",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_TN_-_Principe",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_IT_-_Principe",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_IT_-_Mise_en_oeuvre_des_protections",0,""]]},{"t":"p","s":[["Cadre technique : série NF C 15-100 pour l’installation ; NF C 18-510 pour les opérations électriques. Vérifier l’édition applicable au projet. Pour un site hors de France, vérifier aussi le cadre local et les prescriptions du distributeur.",0,""]]}],"questions":[],"id":"sT3-8"}],"corrige":[]},{"id":"T4","tp":"terre","num":"4","code":"Comparaison","badge":"Comp.","titre":"Comparer les trois régimes et conseiller Marie","sections":[{"titre":"Votre mission en quatre heures","kind":"mission","blocks":[{"t":"p","s":[["Votre mission : ",1,""],["Trois ateliers sont en TT, TN et IT. Marie vous demande : « Quel système convient à mon site, et que dois-je faire lorsqu’un défaut apparaît ? » Vous préparez une réponse fondée sur les schémas et les calculs.",0,""]]},{"t":"h3","text":"Objectifs observables"},{"t":"p","s":[["1. Comparer les trajets du défaut et les moyens de protection.",0,""]]},{"t":"p","s":[["2. Appliquer la bonne relation de calcul à chaque cas.",0,""]]},{"t":"p","s":[["3. Justifier une solution selon la source, la continuité de service et la maintenance.",0,""]]},{"t":"p","s":[["Prérequis : Les trois activités précédentes ; lecture des schémas TT, TN-S et IT.",0,""]]},{"t":"p","s":[["Savoirs associés : Synthèse des SLT ; contraintes d’exploitation ; documentation ; argumentation technique ; prévention.",0,""]]},{"t":"table","rows":[[[[["Durée",1,""]]],[[["Travail",1,""]]]],[[[["20 min",0,""]]],[[["Lire la mission, les objectifs et les consignes.",0,""]]]],[[[["40 min",0,""]]],[[["Comprendre les notions et lire les schémas.",0,""]]]],[[[["60 min",0,""]]],[[["Réaliser les calculs guidés.",0,""]]]],[[[["15 min",0,""]]],[[["Pause.",0,""]]]],[[[["60 min",0,""]]],[[["Traiter le dossier de diagnostic ou de choix ; exercice violet.",0,""]]]],[[[["25 min",0,""]]],[[["Répondre au questionnaire et expliquer ses résultats.",0,""]]]],[[[["20 min",0,""]]],[[["Compléter la synthèse et la grille avec l’enseignant.",0,""]]]]]},{"t":"p","s":[["Total : 240 min, pause comprise. En autonomie : lire → repérer → calculer → expliquer → demander validation. Les exercices violets proposent un approfondissement.",0,""]]}],"questions":[],"id":"sT4-0"},{"titre":"Comprendre avant de calculer","kind":"normal","blocks":[{"t":"h3","text":"Même objectif de protection"},{"t":"p","s":[["TT, TN et IT organisent les liaisons de la source et des masses. Aucun n’est un bouclier absolu : les protections, leur coordination, leur maintien en état et les conditions d’exploitation restent nécessaires.",0,""]]},{"t":"h3","text":"Des réactions différentes"},{"t":"p","s":[["TT : on étudie surtout terre et dispositif différentiel résiduel. TN : on étudie la boucle métallique et la coupure. IT : on étudie le premier défaut, l’alarme et la maintenance, puis la coupure au second défaut.",0,""]]},{"t":"h3","text":"Un choix contraint"},{"t":"p","s":[["Le SLT dépend du réseau disponible, des prescriptions applicables, des récepteurs, des conséquences d’un arrêt et des moyens de maintenance. On ne transforme pas librement le réseau du distributeur au niveau d’un appareil.",0,""]]},{"t":"h3","text":"Adapter au lieu"},{"t":"p","s":[["Les cas de ce module utilisent des hypothèses françaises pour former au raisonnement MELEC. Pour un projet au Bénin, vérifier les règles du pays, les prescriptions du distributeur et les notices. Un site isolé ou un groupe électrogène n’est pas automatiquement en IT.",0,""]]},{"t":"h3","text":"Les mots à employer"},{"t":"p","s":[["Électrisation : passage d’un courant dans le corps. Électrocution : électrisation mortelle. Contact direct : contact avec une partie active. Contact indirect : contact avec une masse devenue dangereuse à la suite d’un défaut. Le module étudie surtout les contacts indirects.",0,""]]},{"t":"h3","text":"Repères de lecture"},{"t":"p","s":[["L : phase ; N : neutre ; PE : conducteur de protection ; QF : disjoncteur. Trait rouge pointillé : défaut ou retour du défaut ; vert : liaison de protection ; bleu : neutre ; brun ou noir : phases. Les couleurs servent à lire le dessin ; elles ne donnent pas à elles seules une prescription de câblage.",0,""]]}],"questions":[],"id":"sT4-1"},{"titre":"Relire le schéma TT","kind":"normal","blocks":[{"t":"img","src":"64f17d4238.png"},{"t":"p","s":[["Schéma fonctionnel de principe. Les détails de réalisation et certaines protections ne sont pas représentés.",0,""]]},{"t":"p","s":[["Lecture : ",1,""],["Repérez la source, la masse, la liaison de terre, le trajet du défaut et l’appareil qui réagit.",0,""]]}],"questions":[],"id":"sT4-2"},{"titre":"Relire le schéma TN","kind":"normal","blocks":[{"t":"img","src":"c3b35af5ab.png"},{"t":"p","s":[["Schéma fonctionnel de principe. Les détails de réalisation et certaines protections ne sont pas représentés.",0,""]]},{"t":"p","s":[["Lecture : ",1,""],["Repérez la source, la masse, la liaison de terre, le trajet du défaut et l’appareil qui réagit.",0,""]]}],"questions":[],"id":"sT4-3"},{"titre":"Relire le schéma IT","kind":"normal","blocks":[{"t":"img","src":"fba0bf4312.png"},{"t":"p","s":[["Schéma fonctionnel de principe. Les détails de réalisation et certaines protections ne sont pas représentés.",0,""]]},{"t":"p","s":[["Lecture : ",1,""],["Repérez la source, la masse, la liaison de terre, le trajet du défaut et l’appareil qui réagit.",0,""]]}],"questions":[],"id":"sT4-4"},{"titre":"Construire le tableau comparatif","kind":"normal","blocks":[{"t":"table","rows":[[[[["Critère",1,""]]],[[["TT",1,""]]],[[["TN",1,""]]],[[["IT",1,""]]]],[[[["Liaison de la source à la terre",0,""]]],[],[],[]],[[[["Liaison des masses",0,""]]],[],[],[]],[[[["Retour du courant de défaut",0,""]]],[],[],[]],[[[["Appareil ou moyen principal",0,""]]],[],[],[]],[[[["Réaction au premier défaut",0,""]]],[],[],[]],[[[["Travail de maintenance",0,""]]],[],[],[]]]},{"t":"p","s":[["Complétez avec des mots courts. Pour IT, distinguez premier défaut et second défaut sur des conducteurs différents.",0,""]]},{"t":"q","num":"Synthèse","id":"q-T4-Synthese","s":[["Quel régime privilégie la continuité au premier défaut, et à quelles conditions ?",0,""]],"v":false,"feuille":true}],"questions":[{"num":"Synthèse","id":"q-T4-Synthese","court":"Quel régime privilégie la continuité au premier défaut, et à quelles c"}],"id":"sT4-5"},{"titre":"Calculer et interpréter","kind":"normal","blocks":[{"t":"p","s":[["Cas A — TT : R_A = 120 Ω, dispositif différentiel résiduel de sensibilité IΔn = 500 mA, U_L = 50 V.\nCas B — TN-S : U₀ = 230 V, Z_s = 1,20 Ω, I_a = 160 A avec coupure garantie < 0,1 s ; critère 0,4 s.\nCas C — IT au premier défaut : I_d1 = 0,020 A, R_A = 100 Ω, U_L = 50 V. Le CPI signale le défaut.",0,""]]},{"t":"p","s":[["TT : R_A × IΔn ≤ U_L",1,""]]},{"t":"p","s":[["TN : I_d = U₀ / Z_s ; comparer à I_a et au temps requis",1,""]]},{"t":"p","s":[["IT au premier défaut : U_c1 = R_A × I_d1",1,""]]},{"t":"q","num":"1","id":"q-T4-1","s":[["Cas A : calculez R_A × IΔn et concluez. Un dispositif différentiel résiduel 300 mA satisferait-il cette seule condition ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"2","id":"q-T4-2","s":[["Cas B : calculez I_d et concluez à partir des données de coupure.",0,""]],"v":false,"feuille":true},{"t":"q","num":"3","id":"q-T4-3","s":[["Cas C : calculez U_c1. Quelle action faut-il organiser malgré ce résultat ?",0,""]],"v":false,"feuille":true}],"questions":[{"num":"1","id":"q-T4-1","court":"Cas A : calculez R_A × IΔn et concluez. Un dispositif différentiel résiduel 300 mA satisferait-il c"},{"num":"2","id":"q-T4-2","court":"Cas B : calculez I_d et concluez à partir des données de coupure."},{"num":"3","id":"q-T4-3","court":"Cas C : calculez U_c1. Quelle action faut-il organiser malgré ce résul"}],"id":"sT4-6"},{"titre":"Enquêter et approfondir","kind":"normal","blocks":[{"t":"p","s":[["Trois sites : A, petit atelier alimenté par un distributeur qui impose TT ; B, atelier avec transformateur privé, PE fiable et arrêts acceptables ; C, processus industriel avec source dédiée, continuité prioritaire et équipe de maintenance qualifiée disponible.",0,""]]},{"t":"q","num":"4","id":"q-T4-4","s":[["Proposez un SLT pour chaque site et donnez deux arguments. Pour B et C, précisez ce qui doit encore être étudié.",0,""]],"v":false,"feuille":true},{"t":"q","num":"5","id":"q-T4-5","s":[["Un responsable veut choisir IT pour ne plus entretenir les protections. Rédigez une réponse en trois phrases.",0,""]],"v":false,"feuille":true},{"t":"q","num":"6","id":"q-T4-6","s":[["Rédigez le compte rendu final : choix, calcul déterminant, limite de votre conclusion et contrôle restant à effectuer.",0,""]],"v":false,"feuille":true},{"t":"q","num":"V4","id":"q-T4-V4","s":[["Un collègue affirme : « Le courant ne prend que le chemin le plus facile ! » Corrigez cette phrase. Expliquez pourquoi une personne peut encore être traversée par un courant si elle touche une masse en défaut, même lorsqu’un PE est présent.",0,"v"]],"v":true,"feuille":true}],"questions":[{"num":"4","id":"q-T4-4","court":"Proposez un SLT pour chaque site et donnez deux arguments. Pour B et C"},{"num":"5","id":"q-T4-5","court":"Un responsable veut choisir IT pour ne plus entretenir les protections"},{"num":"6","id":"q-T4-6","court":"Rédigez le compte rendu final : choix, calcul déterminant, limite de v"},{"num":"V4","id":"q-T4-V4","court":"Un collègue affirme : « Le courant ne prend que le chemin le plus"}],"id":"sT4-7"},{"titre":"Réviser les savoirs","kind":"questionnaire","blocks":[{"t":"p","s":[["Sans regarder le cours, répondez en une ou deux phrases. Revenez ensuite au document pour compléter vos réponses avec une autre couleur.",0,""]]},{"t":"q","num":"R1","id":"q-T4-R1","s":[["Quel régime utilise principalement un retour de défaut par les prises de terre ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"R2","id":"q-T4-R2","s":[["Dans quel régime étudie-t-on surtout une boucle phase–PE métallique ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"R3","id":"q-T4-R3","s":[["Quel régime nécessite de rechercher un premier défaut signalé par CPI ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"R4","id":"q-T4-R4","s":[["Une valeur U_c calculée suffit-elle à valider toute une installation ?",0,""]],"v":false,"feuille":true},{"t":"q","num":"R5","id":"q-T4-R5","s":[["Citez deux mesures de protection communes aux trois régimes.",0,""]],"v":false,"feuille":true}],"questions":[{"num":"R1","id":"q-T4-R1","court":"Quel régime utilise principalement un retour de défaut par les prises "},{"num":"R2","id":"q-T4-R2","court":"Dans quel régime étudie-t-on surtout une boucle phase–PE métallique ?"},{"num":"R3","id":"q-T4-R3","court":"Quel régime nécessite de rechercher un premier défaut signalé par CPI "},{"num":"R4","id":"q-T4-R4","court":"Une valeur U_c calculée suffit-elle à valider toute une installation ?"},{"num":"R5","id":"q-T4-R5","court":"Citez deux mesures de protection communes aux trois régimes."}],"id":"sT4-8"},{"titre":"Faire le bilan de ses compétences","kind":"bilan","blocks":[{"t":"p","s":[["Nom : ________________________    Date : ______________",0,""]]},{"t":"p","s":[["Pour chaque ligne observée, cocher un seul niveau. L’élève se positionne d’abord ; l’enseignant échange avec lui et valide les éléments observés. Les critères portent sur cette activité, pas sur la totalité de la compétence.",0,""]]},{"t":"table","rows":[[[[["Compétence et critère observé",1,""]]],[[["Non\nacquis",1,""]]],[[["En cours\nd’acquisition",1,""]]],[[["Acquis",1,""]]]],[[[["C1 — Analyser les conditions de l’opération et son contexte\nIdentifie les contraintes de chacun des trois sites.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]],[[[["C3 — Définir une installation à l’aide de solutions préétablies\nPropose un SLT compatible et justifie ses limites.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]],[[[["C7 — Valider le fonctionnement de l’installation\nConfronte les résultats aux critères du dossier.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]],[[[["C13 — Communiquer avec le client/usager sur l’opération\nExplique la protection et les consignes avec des mots accessibles.",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]],[[["☐",0,""]]]]]},{"t":"h3","text":"Ma synthèse"},{"t":"p","s":[["À retenir : ",1,""],["Expliquez comment les protections étudiées dans cette activité limitent le danger d’un défaut.",0,""]]},{"t":"p","s":[["À retravailler : ",1,""],["Quel point voulez-vous revoir et avec quelle aide ?",0,""]]},{"t":"p","s":[["Validation enseignant : ____________________   Observation : ____________________",0,""]]}],"questions":[],"id":"sT4-9"},{"titre":"Ressources et repères","kind":"ressource","blocks":[{"t":"h3","text":"Dossiers de travail"},{"t":"p","s":[["Dossier technique : schémas, hypothèses et caractéristiques fournis dans cette activité. Dossier supports : calculatrice, crayons, ordinateur avec LibreOffice Calc ou simulateur préparé. Dossier santé et sécurité : consignes ci-dessous et règles de l’établissement.",0,""]]},{"t":"h3","text":"Conditions de travail"},{"t":"p","s":[["Les calculs utilisent des données d’exercice, pas des réglages à recopier sur une installation. U_L = 50 V alternatif est la valeur conventionnelle retenue ici ; certaines situations imposent d’autres limites. Les temps requis dépendent notamment du réseau, du circuit et des prescriptions applicables.",0,""]]},{"t":"p","s":[["Travail sur documents et simulateur. Aucun contact d’une personne avec une partie électrique, aucun court-circuit ni défaut créé sur le secteur. Toute manipulation réelle exige un support pédagogique adapté, une procédure validée et l’encadrement de l’enseignant. La réalisation de ce module ne constitue pas une habilitation.",0,""]]},{"t":"h3","text":"Références consultées le 3 octobre 2026"},{"t":"p","s":[["Référentiel MELEC 2024 : compétences C1 à C13. Les compétences retenues figurent dans la grille de cette activité. La mise en page reprend le modèle enseignant joint.",0,""]]},{"t":"p","s":[["https://sti.eduscol.education.fr/textes/bac-pro-des-metiers-de-lelectricite-et-de-ses-environnements-connectes",0,""]]},{"t":"p","s":[["INRS — Accidents d’origine électrique et prévention du risque électrique.",0,""]]},{"t":"p","s":[["https://www.inrs.fr/risques/electriques/accidents-origine-electrique.html\nhttps://www.inrs.fr/risques/electriques/prevention-risque-electrique.html",0,""]]},{"t":"p","s":[["Schneider Electric — Guide de l’installation électrique : principes TT, TN et IT ; mise en œuvre des protections IT. Appui explicatif, à compléter avec les textes applicables et les notices.",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_TT_-_Principe",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_TN_-_Principe",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_IT_-_Principe",0,""]]},{"t":"p","s":[["https://fr.electrical-installation.org/frwiki/Schéma_IT_-_Mise_en_oeuvre_des_protections",0,""]]},{"t":"p","s":[["Cadre technique : série NF C 15-100 pour l’installation ; NF C 18-510 pour les opérations électriques. Vérifier l’édition applicable au projet. Pour un site hors de France, vérifier aussi le cadre local et les prescriptions du distributeur.",0,""]]}],"questions":[],"id":"sT4-10"}],"corrige":[]}]};
